#include <stdio.h>
#define MAX_SIZE 10

int queueArr[MAX_SIZE];
int front = 0, rear = 0;

void enqueue(int num){
    queueArr[rear++] = num;
}

int dequeue(){
    return queueArr[front++];
}

int main(){
    enqueue(1); enqueue(2); enqueue(3);
    printf("%d", dequeue());
    enqueue(4);
    printf("%d", dequeue());
    printf("%d", dequeue());
    enqueue(5); enqueue(6);
    printf("%d", dequeue());
    printf("%d", dequeue());
    printf("%d", dequeue());
    return 0;
}

