int gcd(int a, int b) {
  if (b == 0) return a;
  return gcd(b, a % b);
}
int main(){
  printf("%d", gcd(48, 18));
}

class Parent {
    public int compute(int num){
        if(num <= 0) return 0;
        return num + compute(num - 1);
    }
}
class Child extends Parent {
    public int compute(int num){
        if(num <= 0) return 0;
        return super.compute(num) + compute(num - 2);
    }
}
class Main {
    public static void main(String[] args){
        Parent obj = new Child();
        System.out.print(obj.compute(4));
    }
}

#include <stdio.h>
int fib(int n, int memo[]) {
    if (n <= 1) return n;
    if (memo[n] != -1) return memo[n];
    memo[n] = fib(n-1, memo) + fib(n-2, memo);
    return memo[n];
}
int main() {
    int n = 10;
    int memo[11];
    for (int i = 0; i <= n; i++) memo[i] = -1;
    printf("%d", fib(n, memo));
    return 0;
}
